package com.celik.kingdoms;
import java.util.*;
import static com.celik.kingdoms.AirDropConfig.*;
/** Balance defaults from the approved loot specification. Probabilities are per crate. */
final class AirDropLootDefaults {
    static Loot item(String name,int weight,int min,int max){return new Loot("minecraft:"+name,weight,min,max);}
    static Loot enchanted(String item,int weight,String enchantment,int level){Loot l=item(item,weight,1,1);l.enchantments.put("minecraft:"+enchantment,level);return l;}
    static Loot potion(String potion,int weight){Loot l=item("potion",weight,1,2);l.potion="minecraft:"+potion;return l;}
    static List<Variant> variants(){List<Variant> result=new ArrayList<>();String[] keys={"standard","resource","combat","enchantment","armory","elite","legendary","mythic"},names={"Standard supply drop","Resource cache","Combat cache","Enchantment cache","Armory cache","Elite cache","Legendary cache","Mythic cache"};int[] weights={6000,1200,1000,700,500,400,180,20};for(int i=0;i<8;i++){Variant v=new Variant(keys[i],names[i],weights[i]);if(i==1)v.categoryMultipliers.putAll(Map.of("basic",1.5,"valuable",1.5,"diamonds",1.5,"combat",0.5));if(i==2||i==4)v.categoryMultipliers.putAll(Map.of("combat",1.5,"potions",1.25,"basic",0.5));if(i==3)v.categoryMultipliers.putAll(Map.of("enchantment",2.0,"basic",0.5,"combat",0.5));if(i>=5)v.categoryMultipliers.putAll(Map.of("enchantment",1.25,"diamonds",1.25,"combat",1.25));if(i==6)v.rarityMultiplier=2;if(i==7)v.rarityMultiplier=3;result.add(v);}return result;}
    static List<Tier> tiers(){List<Tier> result=new ArrayList<>();int[] days={1,3,5,7};double[][] chances={{.90,.85,.30,.08,.10,.25,0,0,0,.02},{.80,.65,.50,.30,.25,.40,.25,.05,0,.04},{.70,.45,.65,.45,.45,.55,.40,.15,0,.08},{.60,.30,.70,.55,.60,.65,.50,.30,.25,.12}};
        for(int i=0;i<4;i++){
            Tier t=new Tier(new String[]{"early game","nether unlocked","advanced","endgame"}[i],days[i]);t.minRolls=5+i;t.maxRolls=12;t.entries.addAll(List.of(item("iron_ingot",100,8,24),item("cooked_beef",100,8,24),item("arrow",80,8,32),item("coal",80,8,24)));
            t.categories.add(new Category("survival",chances[i][0],List.of(item("cooked_beef",120,8,24),item("arrow",100,8,32),item("string",60,4,12),item("saddle",20,1,1),item("name_tag",20,1,1))));
            if(i>0)t.categories.getFirst().entries=new ArrayList<>(t.categories.getFirst().entries);if(i>0)t.categories.getFirst().entries.add(item("ender_pearl",40,2,4+i));
            t.categories.add(new Category("basic",chances[i][1],List.of(item("iron_ingot",120,8+i*4,24+i*2),item("coal",100,8,24),item("copper_ingot",90,16,32),item("iron_block",30,1,3+i),item("obsidian",60,2+i*2,6+i*3))));
            t.categories.add(new Category("valuable",chances[i][2],List.of(item("gold_ingot",100,4+i*4,12+i*4),item("gold_block",i==0?5:30,1,1+i),item("redstone",100,8,24),item("lapis_lazuli",100,8,16+i*4),item("emerald_block",i<3?1:20,1,3))));
            t.categories.add(new Category("diamonds",chances[i][3],List.of(item("diamond",100,i==0?1:i*2,i==0?3:4+i*4))));
            List<Loot> books=new ArrayList<>(List.of(item("experience_bottle",140,2+i*2,6+i*4),item("lapis_lazuli",100,8,16),enchanted("enchanted_book",60,"protection",Math.min(4,i+1)),enchanted("enchanted_book",60,"sharpness",i==3?5:i+1),enchanted("enchanted_book",60,"efficiency",i==3?5:i+1),enchanted("enchanted_book",50,"power",i==3?5:i+1),item("anvil",20,1,1)));if(i==3)books.addAll(List.of(enchanted("enchanted_book",30,"mending",1),enchanted("enchanted_book",45,"unbreaking",3)));t.categories.add(new Category("enchantment",chances[i][4],books));
            List<Loot> combat=new ArrayList<>(List.of(enchanted(i==0?"iron_sword":"diamond_sword",100,"sharpness",i==3?5:i+1),enchanted(i==0?"iron_chestplate":"diamond_chestplate",100,"protection",Math.min(4,i+1)),enchanted(i==0?"iron_pickaxe":"diamond_pickaxe",70,"efficiency",i==3?5:i+1),enchanted("bow",90,"power",i==3?5:i+1),item("crossbow",50,1,1),item("shield",80,1,1),item("arrow",100,16,32)));if(i==3)combat.addAll(List.of(enchanted("netherite_sword",2,"sharpness",5),enchanted("netherite_chestplate",2,"protection",4)));t.categories.add(new Category("combat",chances[i][5],combat));
            t.categories.add(new Category("potions",chances[i][6],List.of(potion("long_fire_resistance",100),potion("strong_strength",60),potion("long_swiftness",60),item("blaze_rod",90,2,4),item("nether_wart",90,2,8),item("quartz",100,8,24))));
            t.categories.add(new Category("netherite",chances[i][7],List.of(item("netherite_scrap",10,1,i>=2?3:1),item("quartz",120,8,24),item("obsidian",120,4,12))));
            t.categories.add(new Category("end",chances[i][8],List.of(item("shulker_shell",20,1,2),item("end_stone",120,16,32),item("chorus_fruit",100,8,16),item("purpur_block",80,8,24))));
            Loot cosmetic=item("amethyst_shard",100,1,1);cosmetic.name="AirDrop victor's token";cosmetic.lore=List.of("A collectible from a contested supply drop.");cosmetic.glint=true;t.categories.add(new Category("cosmetic",chances[i][9],List.of(cosmetic)));
            result.add(t);
        }return result;
    }
    static List<Rare> rare(){List<Rare> result=new ArrayList<>();result.add(new Rare("golden_apple",item("golden_apple",100,1,2),.005,.03,.08,.15));result.add(new Rare("enchanted_golden_apple",item("enchanted_golden_apple",100,1,1),0,.0005,.0025,.01));result.add(new Rare("totem",item("totem_of_undying",100,1,1),0,.001,.005,.02));result.add(new Rare("trident",enchanted("trident",100,"loyalty",3),0,.001,.005,.02));result.add(new Rare("upgrade_template",item("netherite_upgrade_smithing_template",100,1,1),0,.002,.01,.03));result.add(new Rare("netherite_ingot",item("netherite_ingot",100,1,1),0,.001,.005,.02));result.add(new Rare("elytra",item("elytra",100,1,1),0,0,0,.005));result.add(new Rare("beacon",item("beacon",100,1,1),0,0,.001,.005));result.add(new Rare("nether_star",item("nether_star",100,1,1),0,0,0,.0025));return result;}
    private AirDropLootDefaults(){}
}
